下面函数接收已经解析的 unknown 数据，只返回新建的合法指令对象或 null。不要使用类型断言直接把模型结果当成已验证的 Decision。

```ts
type Decision = {
  mode: "FOLLOW" | "WAIT" | "HINT";
  hintId: string | null;
};
type Context = {
  canFollow: boolean;
  unlockedHints: readonly string[];
};

export function validateDecision(
  input: unknown, ctx: Context
): Decision | null {
  if (!input || typeof input !== "object" || Array.isArray(input)) {
    return null;
  }
  const v = input as Record<string, unknown>;
  const keys = Object.keys(v);
  if (keys.length !== 2 || !keys.includes("mode") || !keys.includes("hintId")) {
    return null;
  }
  switch (v.mode) {
    case "FOLLOW":
      return ctx.canFollow && v.hintId === null
        ? { mode: "FOLLOW", hintId: null } : null;
    case "WAIT":
      return v.hintId === null ? { mode: "WAIT", hintId: null } : null;
    case "HINT":
      return typeof v.hintId === "string" && ctx.unlockedHints.includes(v.hintId)
        ? { mode: "HINT", hintId: v.hintId } : null;
    default:
      return null;
  }
}
```

生产环境还要限制请求与响应大小，捕获 JSON.parse 失败，并处理服务拒绝、空结果和网络错误。校验失败时使用固定的本地回退，例如进入 WAIT 并显示“我没理解，请用按钮选择”。不要把失败结果自动放宽成另一个有副作用的动作。

这段函数只检查结构和两个业务条件，不负责身份验证、路径可达性或消息去重。执行前用最新状态再检查一次；提示已被取消、队友已死亡或场景已切换时，旧结果应丢弃。
